import json, sys
raw = json.loads(sys.stdin.read())
result_str = raw['result']
registry = json.loads(result_str)
exps = registry['data']['experiments']
# exps might be a dict keyed by exp_id
if isinstance(exps, dict):
    items = list(exps.items())
elif isinstance(exps, list):
    items = [(e.get('exp_id','?'), e) for e in exps]
else:
    print(type(exps))
    sys.exit(1)

from collections import Counter
c = Counter()
for eid, e in items:
    if isinstance(e, str):
        e2 = json.loads(e) if e.startswith('{') else {'status': 'unknown'}
    else:
        e2 = e
    st = e2.get('status', 'unknown')
    c[st] += 1
    if st in ('RUNNING', 'PREPARING', 'QUEUED', 'ALLOCATED', 'PENDING'):
        print(f'{eid}: status={st}')
        spec = e2.get('spec', {})
        if spec:
            print(f'  server={spec.get(\"server\",\"?\")}, gpu={spec.get(\"gpu\",\"?\")}, pid={spec.get(\"pid\",\"?\")}')
        if e2.get('cron_id'):
            print(f'  cron_id={e2[\"cron_id\"]}')
        hyp = e2.get('hypothesis','')
        if hyp:
            print(f'  hypothesis={hyp[:100]}')
        print()

print('--- Status counts ---')
for s, n in sorted(c.items()):
    print(f'{s}: {n}')
"
